const void *key = argkey;
const void *data = argdata;
size_t hashes[2];
size_t bucket = argbucket;
unsigned i;

// Limit the number of eviction/relocation attempts to prevent infinite loops.
const size_t max_iterations = (ZU(1) << (ckh->lg_curbuckets + 1));
size_t iterations = 0;

while (iterations++ < max_iterations) {
    // Choose a random item within the bucket to evict.
    i = (unsigned)prng_lg_range_u64(&ckh->prng_state, LG_CKH_BUCKET_CELLS);
    ckhc_t *cell = &ckh->tab[(bucket << LG_CKH_BUCKET_CELLS) + i];
    assert(cell->key != NULL);

    // Swap cell->{key,data} and {key,data} (evict).
    const void *tkey = cell->key;
    const void *tdata = cell->data;
    cell->key = key;
    cell->data = data;
    key = tkey;
    data = tdata;

#ifdef CKH_COUNT
    ckh->nrelocs++;
#endif

    // Find the alternate bucket for the evicted item.
    ckh->hash(key, hashes);
    size_t tbucket = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);
    if (tbucket == bucket) {
        tbucket = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
    }

    // Check for a cycle.
    if (tbucket == argbucket) {
        return true;
    }

    bucket = tbucket;

    // Try to insert the evicted item in its new bucket.
    if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
        return false;
    }
}

// Max iterations reached without successful insertion.
return true;

